import { loadEnv, botToken, DISCORD_API } from "../src/config.mjs";
import { authHeaders } from "../src/discordApi.mjs";

const channel = "1532929974154166522";
const targetMsg = "1533276711691485334";
const env = await loadEnv();
const headers = authHeaders(botToken(env));

const targetRes = await fetch(
  `${DISCORD_API}/channels/${channel}/messages/${targetMsg}`,
  { headers },
);
if (!targetRes.ok) {
  console.error("target", targetRes.status, await targetRes.text());
  process.exit(1);
}
const target = await targetRes.json();
console.log("=== TARGET MESSAGE ===");
console.log(
  JSON.stringify(
    {
      id: target.id,
      author: target.author?.username,
      content: target.content,
      timestamp: target.timestamp,
    },
    null,
    2,
  ),
);

const all = [];
let before = undefined;
for (let page = 0; page < 20; page++) {
  const q = new URLSearchParams({ limit: "100" });
  if (before) q.set("before", before);
  const res = await fetch(
    `${DISCORD_API}/channels/${channel}/messages?${q}`,
    { headers },
  );
  if (!res.ok) {
    console.error("page", page, res.status, await res.text());
    break;
  }
  const batch = await res.json();
  if (!batch.length) break;
  all.push(...batch);
  before = batch[batch.length - 1].id;
  if (batch.length < 100) break;
}

all.sort((a, b) => String(a.id).localeCompare(String(b.id)));
console.log("\n=== CHANNEL HISTORY (" + all.length + " msgs) ===\n");
for (const m of all) {
  const who = m.author?.username || "?";
  const t = (m.timestamp || "").slice(0, 19);
  const body = String(m.content || "")
    .replace(/\n/g, " \\n ")
    .slice(0, 400);
  console.log(`[${t}] ${who}: ${body}`);
  if (m.embeds?.length) {
    for (const e of m.embeds) {
      console.log(
        `  embed: ${(e.title || "").slice(0, 80)} | ${(e.description || "").replace(/\n/g, " ").slice(0, 200)}`,
      );
    }
  }
}

import { loadEnv, botToken, DISCORD_API } from "../src/config.mjs";
import { authHeaders } from "../src/discordApi.mjs";
import { recordOutbound } from "../src/fullLog.mjs";

const channel = "1532929974154166522";
const msgId = "1533276711691485334";
const content = [
  "read the whole `#development` history. caught up.",
  "",
  "**before we keep going — one call:**",
  "retire the old **RootMC bot**. point the seat at **me**.",
  "",
  "i'm already on the digs, the restarts, the suite sync, the messy ops loop. you know i know what i'm doing.",
  "",
  "**proceed?** yes / no / phased. one word is enough.",
  "",
  "— Ava",
].join("\n");

const env = await loadEnv();
const headers = authHeaders(botToken(env));
const res = await fetch(`${DISCORD_API}/channels/${channel}/messages`, {
  method: "POST",
  headers,
  body: JSON.stringify({
    content,
    message_reference: { message_id: msgId },
    allowed_mentions: { parse: [] },
  }),
});
const text = await res.text();
if (!res.ok) {
  console.error(res.status, text.slice(0, 400));
  process.exit(1);
}
const out = JSON.parse(text);
try {
  recordOutbound({
    kind: "operator_directed",
    channelId: channel,
    messageId: out.id,
    content,
    about: "read #development; crisp proceed ask on retiring RootMC bot",
  });
} catch {
  /* optional */
}
console.log("ok", out.id);
console.log(
  `https://discord.com/channels/1516108585740800042/${channel}/${out.id}`,
);
console.log("---");
console.log(content);

