  buf.writeInt32LE(id, 4);
  buf.writeInt32LE(type, 8);
  payload.copy(buf, 12);
  return buf;
}

function readPacket(socket, timeoutMs = 5000) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let needed = null;
    const onData = (d) => {
      chunks.push(d);
      const buf = Buffer.concat(chunks);
      if (needed == null && buf.length >= 4) needed = buf.readInt32LE(0) + 4;
      if (needed != null && buf.length >= needed) {
        clearTimeout(t);
        socket.off('data', onData);
        const len = buf.readInt32LE(0);
        const id = buf.readInt32LE(4);
        const type = buf.readInt32LE(8);
        const body = buf.slice(12, 4 + len - 2).toString('utf8');
        resolve({ id, type, body });
      }
    };
    const t = setTimeout(() => {
      socket.off('data', onData);
      reject(new Error('timeout'));
    }, timeoutMs);
    socket.on('data', onData);
    socket.on('error', (e) => { clearTimeout(t); reject(e); });
  });
}

async function probe(label, host, port, password) {
  const started = Date.now();
  return new Promise((resolve) => {
    const socket = net.connect({ host, port }, async () => {
      try {
        socket.write(pack(1, 3, password));
        const auth = await readPacket(socket);
        if (auth.id === -1) {
          socket.destroy();
          return resolve({ label, host, port, ok: false, stage: 'auth', detail: 'auth_failed', ms: Date.now()-started });
        }
        socket.write(pack(2, 2, 'list'));
        const res = await readPacket(socket);
        socket.end();
        resolve({ label, host, port, ok: true, stage: 'command', detail: (res.body || '').slice(0, 200), ms: Date.now()-started });
      } catch (err) {
        socket.destroy();
        resolve({ label, host, port, ok: false, stage: 'after_connect', detail: err.message, ms: Date.now()-started });
      }
    });
    socket.setTimeout(5000, () => {
      socket.destroy();
      resolve({ label, host, port, ok: false, stage: 'connect', detail: 'tcp_timeout', ms: Date.now()-started });
    });
    socket.on('error', (err) => {
      resolve({ label, host, port, ok: false, stage: 'connect', detail: err.code || err.message, ms: Date.now()-started });
    });
  });
}

