export function dreamStateConfigured(env = {}) {
  const key =
    String(process.env.AVA_XAI_API_KEY || env.AVA_XAI_API_KEY || process.env.XAI_API_KEY || env.XAI_API_KEY || "").trim() ||
    String(process.env.AVA_GROK_API_KEY || env.AVA_GROK_API_KEY || "").trim();
  return Boolean(key);
}

