  reactors = null,
}) {
  const prev = readJson(messagePath(messageId), null);
  const nextReactors =
    reactors && typeof reactors === "object"
      ? reactors
      : prev?.reactors && typeof prev.reactors === "object"
        ? prev.reactors
        : {};
  const record = {
