 * Disable: AVA_NO_STATUS_WINDOW=1 (also auto on Linux / SSH / non-TTY)
 */
function openStatusWindow() {
  if (isHeadlessHost()) {
    console.log(`Ava status (headless) → ${statusUrl} (ssh -L ${AVA_PORT}:127.0.0.1:${AVA_PORT})`);
