Get-Content $errLog -Tail 15 -ErrorAction SilentlyContinue
# Probe public URL
Start-Sleep 5
try {
  $r = Invoke-WebRequest -Uri "https://ava.rootmc.net/" -UseBasicParsing -TimeoutSec 20
  "public status=$($r.StatusCode) len=$($r.Content.Length)"
} catch { "public err: $($_.Exception.Message)" }
nslookup ava.rootmc.net 1.1.1.1 2>&1 | Select-Object -First 12

# Force through Cloudflare IPs from 1.1.1.1
Start-Sleep 3
try {
  $r = Invoke-WebRequest -Uri "https://ava.rootmc.net/" -UseBasicParsing -TimeoutSec 25
  "OK status=$($r.StatusCode) bytes=$($r.RawContentLength)"
  if ($r.Content -match 'Ava|status|heartbeat|live') { "content looks like Ava status" }
} catch {
  "err: $($_.Exception.Message)"
  if ($_.Exception.Response) { "http=$([int]$_.Exception.Response.StatusCode)" }
}
# Also try curl.exe which may use different resolver
curl.exe -sI "https://ava.rootmc.net/" --max-time 20 2>&1 | Select-Object -First 15

curl.exe -sI "https://ava.rootmc.net/" --resolve "ava.rootmc.net:443:104.21.26.170" --max-time 25 2>&1 | Select-Object -First 20
curl.exe -s "https://ava.rootmc.net/" --resolve "ava.rootmc.net:443:104.21.26.170" --max-time 25 2>&1 | Select-Object -First 8
# Flush DNS and retry native
ipconfig /flushdns | Out-Null
Start-Sleep 2
try {
  Resolve-DnsName ava.rootmc.net -Type A -ErrorAction Stop | Select-Object Name,IPAddress
  (Invoke-WebRequest -Uri "https://ava.rootmc.net/" -UseBasicParsing -TimeoutSec 25).StatusCode
} catch { "still: $($_.Exception.Message)" }
